const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');

let pos = 0;
const len = data.length;

function nextInt() {
  while (pos < len && data.charCodeAt(pos) <= 32) pos++;
  let x = 0;
  while (pos < len) {
    const c = data.charCodeAt(pos);
    if (c <= 32) break;
    x = x * 10 + (c - 48);
    pos++;
  }
  return x;
}

const n = nextInt();
const a = new Array(n);

for (let i = 0; i < n; i++) {
  a[i] = nextInt();
}

let i = 0;
let j = n - 1;
let operations = 0;

if (n > 0) {
  let left = a[i];
  let right = a[j];

  while (i < j) {
    if (left === right) {
      i++;
      j--;
      if (i < j) {
        left = a[i];
        right = a[j];
      }
    } else if (left < right) {
      i++;
      left += a[i];
      operations++;
    } else {
      j--;
      right += a[j];
      operations++;
    }
  }
}

console.log(operations);
